pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint8 nPuts, uint256 collectAmt, uint32 warpSecs) public {
        vm.assume(nPuts >= 2 && nPuts <= 5);
        vm.assume(collectAmt <= 100 ether);
        vm.assume(warpSecs >= 1 && warpSecs <= 365 days);

        // Deploy and initialize log file
        c.SetMinSum(0);
        c.Initialized();

        address actor = address(uint160(uint256(keccak256(abi.encode(seed))));
        vm.assume(actor != address(0) && actor != address(c));

        uint256 totalDeposited = 0;
        uint256 totalCollected = 0;

        for (uint8 i = 0; i < nPuts; i++) {
            uint256 amt = 1 ether + (uint256(keccak256(abi.encode(seed, i))) % 10 ether);
            vm.deal(actor, amt);
            vm.prank(actor);
            c.Put{value: amt}(uint256(warpSecs) * (i + 1));
            totalDeposited += amt;
        }

        // Warp beyond unlock time of all deposits
        vm.warp(block.timestamp + uint256(warpSecs) * (nPuts + 1));

        // Initial balance sum before any Collect
        uint256 sumBalancesBefore = c.Acc(actor).balance;

        // Collect an amount <= sumBalancesBefore to avoid revert
        uint256 amt = (collectAmt % sumBalancesBefore) + 1;
        vm.prank(actor);
        try c.Collect(amt) {
            totalCollected = amt;
        } catch {
            totalCollected = 0;
        }

        uint256 finalAccBalance = c.Acc(actor).balance;
        // Invariant: after Collect, actor's Acc.balance should be (totalDeposited - totalCollected)
        // if no other actor interfered (none did). Bug sets balance = last msg.value, so fails this.
        assertTrue(finalAccBalance == totalDeposited - totalCollected);
    }
}

