contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 depositAmt, uint256 collectAmt, uint256 minSum) public {
        // Admissible domain: avoid overflow in Put and Collect
        vm.assume(depositAmt > 0 && collectAmt > 0);
        vm.assume(depositAmt <= type(uint256).max - lockTime);
        vm.assume(collectAmt <= depositAmt);
        vm.assume(minSum <= depositAmt);
        vm.assume(lockTime <= type(uint256).max - block.timestamp);

        // Initialize the contract and set MinSum
        vm.prank(address(this));
        c.Initialized();
        c.SetMinSum(minSum);

        // Deploy a Log contract
        C.LogFile log = new C.LogFile();
        c.SetLogFile(address(log));

        // Fund and deposit
        address user = address(0x1234);
        vm.deal(user, depositAmt);
        vm.prank(user);
        c.Put{value: depositAmt}(lockTime);

        // Warp past unlock time so time condition is satisfied
        vm.warp(block.timestamp + lockTime + 1);

        // Call Collect
        bool ok;
        vm.prank(user);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Invariant: if Collect did NOT revert, the user's pre-collect balance must be >= MinSum
        // We check post-collect condition: if it succeeded, initial balance (depositAmt) must have been >= minSum
        if (ok) {
            assertTrue(depositAmt >= minSum);
        }
    }
}

