import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am, uint256 initialDeposit, uint256 unlockTime, uint256 minSum) public {
        address actor = address(0x100);
        vm.assume(actor != address(this));
        vm.assume(minSum >= 0);
        vm.assume(initialDeposit >= minSum);
        vm.assume(_am > initialDeposit);
        vm.assume(unlockTime > 0);
        vm.assume(unlockTime < type(uint256).max - block.timestamp);

        c.SetMinSum(minSum);
        c.SetLogFile(address(0x200));
        c.Initialized();

        vm.deal(actor, initialDeposit);
        vm.startPrank(actor);
        c.Put{value: initialDeposit}(unlockTime);

        uint256 balanceBefore = c.Acc(actor).balance;

        vm.warp(block.timestamp + unlockTime + 1);

        bool ok = true;
        try c.Collect(_am) { ok = true; } catch { ok = false; }
        vm.stopPrank();

        if (ok) {
            assertEq(c.Acc(actor).balance, balanceBefore - _am);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am, uint _lockTime, uint _deposit) public payable {
        require(_deposit > 0 && _am > 0);
        require(address(this).balance >= _deposit);
        c.Put{value: _deposit}(_lockTime);
        uint balBefore = address(c).balance;
        bool reverted; try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        assert(!reverted ? balAfter <= balBefore - _am : true);
    }
    receive() external payable {}
}

